import new_sentry_scope, {capturing} from "@/public/sentry";
import {getOrCreateUserId, tbEvent} from "@/public/customStats";
import Tab = chrome.tabs.Tab;
import {onMessage, sendMessage, FetchUrlRequest, FetchUrlResponse, SizeLimits} from "@/public/messaging";
import {isDevelopmentMode} from "@/public/tools";
import {installRouter} from "@monetize.software/sdk-extension/sw";

// The single offscreen document hosts both download processing (WORKERS) and,
// once wired, the paywall SDK's auth/bootstrap state (LOCAL_STORAGE). Whichever
// side creates the document first declares both reasons so the other can reuse it.
const OFFSCREEN_REASONS = [
    chrome.offscreen.Reason.WORKERS,
    chrome.offscreen.Reason.LOCAL_STORAGE,
];
const OFFSCREEN_JUSTIFICATION =
    "Parsing and downloading web pages, and persisting paywall auth/bootstrap state via localStorage.";

// Mime type patterns to size limit key mapping (matches DownloadTask.ts logic)
const mimeToSizeKey: [string, keyof SizeLimits][] = [
    ["image", "image_max"],
    ["font", "font_max"],
    ["script", "js_max"],
    ["css", "css_max"],
    ["stream", "others_max"],
];

function getMaxSizeForContentType(contentType: string | null, sizeLimits: SizeLimits): number {
    if (contentType) {
        const lowerType = contentType.toLowerCase();
        for (const [mimePattern, sizeKey] of mimeToSizeKey) {
            if (lowerType.includes(mimePattern)) {
                return sizeLimits[sizeKey];
            }
        }
    }
    return sizeLimits.others_max;
}

const FAILED_INJECTION_TABS_KEY = 'failedInjectionTabs';

// Map to store AbortControllers per task for fetch cancellation
const fetchAbortControllers = new Map<string, AbortController>();

// Track sidepanel port connections and their active taskIds
const sidepanelPorts = new Map<chrome.runtime.Port, string | null>();

function getOrCreateAbortController(taskId: string): AbortController {
    if (!fetchAbortControllers.has(taskId)) {
        fetchAbortControllers.set(taskId, new AbortController());
    }
    return fetchAbortControllers.get(taskId)!;
}

// Track tabs where content script injection failed
async function addFailedInjectionTab(tabId: number, url: string) {
    const result = await chrome.storage.local.get([FAILED_INJECTION_TABS_KEY]);
    const failedTabs = result[FAILED_INJECTION_TABS_KEY] || {};
    failedTabs[tabId] = { url, timestamp: Date.now() };
    await chrome.storage.local.set({ [FAILED_INJECTION_TABS_KEY]: failedTabs });
}

async function removeFailedInjectionTab(tabId: number) {
    const result = await chrome.storage.local.get([FAILED_INJECTION_TABS_KEY]);
    const failedTabs = result[FAILED_INJECTION_TABS_KEY] || {};
    delete failedTabs[tabId];
    await chrome.storage.local.set({ [FAILED_INJECTION_TABS_KEY]: failedTabs });
}

// Offscreen document lifecycle management.
//
// The single offscreen document is now created from two independent paths: our
// download flow (here) and the paywall SDK's port router (installRouter). Both
// do a check-then-create, so without coordination they can both pass the
// "exists?" check and both call createDocument — the second of which rejects
// with "Only a single offscreen document may be created", aborting the download.
// We serialize our own creation with an in-flight promise and treat a concurrent
// creation by the SDK as success.
let offscreenCreation: Promise<void> | null = null;

async function ensureOffscreenDocument(): Promise<void> {
    if (await offscreenDocumentExists()) {
        console.log("Offscreen document already exists");
        return;
    }

    if (!offscreenCreation) {
        offscreenCreation = (async () => {
            try {
                console.log("Creating offscreen document");
                await chrome.offscreen.createDocument({
                    url: "offscreen.html",
                    reasons: OFFSCREEN_REASONS,
                    justification: OFFSCREEN_JUSTIFICATION,
                });
            } catch (e: any) {
                // The SDK router may have created it concurrently — that's fine.
                if (!String(e?.message ?? e).includes("Only a single offscreen document")) {
                    throw e;
                }
            } finally {
                offscreenCreation = null;
            }
        })();
    }

    await offscreenCreation;
}

async function offscreenDocumentExists(): Promise<boolean> {
    const offscreenUrl = chrome.runtime.getURL("offscreen.html");
    const existingContexts = await chrome.runtime.getContexts({
        contextTypes: [chrome.runtime.ContextType.OFFSCREEN_DOCUMENT],
        documentUrls: [offscreenUrl],
    });
    return existingContexts.length > 0;
}

// Check if sidepanel API is available
function isSidePanelAvailable(): boolean {
    return typeof chrome !== 'undefined' &&
           typeof chrome.sidePanel !== 'undefined' &&
           typeof chrome.sidePanel.open === 'function';
}

// noinspection JSUnusedGlobalSymbols
export default defineBackground(() => {

    const sentry_scope = new_sentry_scope();

    // Route paywall SDK ports (from the sidepanel's PaywallUI) to the offscreen
    // document. Only handles the SDK's own port name, so it coexists with the
    // 'sidepanel' onConnect listener below. Reuses our persistent offscreen when
    // present, otherwise lazily creates it with both reasons.
    installRouter({
        offscreenUrl: chrome.runtime.getURL("offscreen.html"),
        offscreenReasons: OFFSCREEN_REASONS,
        offscreenJustification: OFFSCREEN_JUSTIFICATION,
    });

    // Check sidepanel availability and set appropriate action
    if (!isSidePanelAvailable()) {
        console.error('Sidepanel API is not available in this browser');
        tbEvent('sidepanel.not_available');
        // Popup is already set in manifest - just keep it
    } else {
        // Sidepanel is available - disable the popup and use normal behavior
        chrome.action.setPopup({ popup: '' });  // Clear popup to enable onClick handler

        chrome.action.onClicked.addListener(async function (tab: Tab) {
            await capturing(sentry_scope, "action_button_clicked_listener", tab.url, async () => {
                await action_button_clicked(tab);
            });
        });

        chrome.sidePanel
            .setPanelBehavior({openPanelOnActionClick: false})
            .catch((error) => {
                console.warn('setPanelBehavior failed:', error);
                tbEvent('sidepanel.set_panel_behavior_failed');
            });
    }

    // Handle sidepanel port connections for cleanup on close
    chrome.runtime.onConnect.addListener((port) => {
        if (port.name !== 'sidepanel') return;

        console.log('Sidepanel connected');
        sidepanelPorts.set(port, null);

        port.onMessage.addListener((message) => {
            if (message.type === 'setTaskId') {
                console.log('Sidepanel set taskId:', message.taskId);
                sidepanelPorts.set(port, message.taskId);
            } else if (message.type === 'clearTaskId') {
                console.log('Sidepanel cleared taskId');
                sidepanelPorts.set(port, null);
            }
        });

        port.onDisconnect.addListener(async () => {
            const taskId = sidepanelPorts.get(port);
            console.log('Sidepanel disconnected, taskId:', taskId);
            sidepanelPorts.delete(port);

            if (taskId) {
                // Cancel the active download
                const controller = fetchAbortControllers.get(taskId);
                if (controller) {
                    controller.abort();
                }

                if (await offscreenDocumentExists()) {
                    await sendMessage('cancelProcessing', taskId);
                }
            }
        });
    });

    onMessage('triggerAction', async (message) => {
        await capturing(sentry_scope, "triggerAction_message_handler", message.sender?.tab?.url, async () => {
            await action_button_clicked(message.sender?.tab as Tab);
        });
    });

    chrome.runtime.onInstalled.addListener((details) => {
        try {
            console.log("Extension installed");
            if (details.reason === chrome.runtime.OnInstalledReason.INSTALL) {
                // Code to be executed on first install
                const showOnboarding = true;
                tbEvent('install', { showOnboarding });

                // Save install date for new users
                const installDate = new Date().toISOString();
                chrome.storage.sync.set({ installDate, showOnboarding });

                // Inject content script into all open tabs that match our URL pattern
                chrome.tabs.query({url: ["http://*/*", "https://*/*"]}, async (tabs) => {
                    for (const tab of tabs) {
                        try {
                            if (
                                tab.id &&
                                tab.url &&
                                !tab.url.startsWith("https://chromewebstore.google.com/")
                            ) {
                                chrome.scripting.executeScript({
                                    target: { tabId: tab.id },
                                    files: ["content-scripts/content.js"]
                                }).catch(async (error) => {
                                    // Track failed injection instead of sending to Sentry
                                    console.warn(`Content script injection failed for tab ${tab.id} (${tab.url}). Will prompt user to reload when they focus this tab.`);
                                    if (tab.id) {
                                        await addFailedInjectionTab(tab.id, tab.url || '');
                                    }
                                });
                            }
                        } catch (error) {
                            console.error(`Failed to manually inject content script into tab ${tab.id}:`, error);
                            const error_new = new Error("Failed to manually inject content script into tab " + tab.url, { cause: error });
                            sentry_scope.captureException(error_new);
                        }
                    }
                });

                // e.g. open a tab with an url
                chrome.tabs.create({
                    url: "https://extensiontechnologies-332ae.web.app/website_downloader",
                });
            } else if (details.reason === chrome.runtime.OnInstalledReason.UPDATE) {
                // When extension is updated
            } else if (details.reason === chrome.runtime.OnInstalledReason.CHROME_UPDATE) {
                // When browser is updated
            } else if (details.reason === chrome.runtime.OnInstalledReason.SHARED_MODULE_UPDATE) {
                // When a shared module is updated
            }
        } catch (e) {
            const error_new = new Error("Error in OnInstalled " + e, { cause: e });
            sentry_scope.captureException(error_new);
        }
    });

    onMessage('reloadCurrentTab', async (message) => {
        await capturing(sentry_scope, "reloadCurrentTab_message_handler", undefined, async () => {
            chrome.tabs.query({active: true, currentWindow: true}, (tabs) => {
                if (tabs[0].id) {
                    // Reload the active tab
                    chrome.tabs.reload(tabs[0].id);
                }
            });
        })
    })

    onMessage('htmlCaptured', async ({ data }) => {
        const { linkDepth } = await chrome.storage.sync.get({ linkDepth: 1 });
        const mode = data.isMultiPage ? "multipage" : "single";
        await capturing(sentry_scope, "htmlCaptured_message_handler", data.url, async () => {
            await ensureOffscreenDocument();
            sendMessage('startProcessing', {
                taskId: data.taskId,
                tabId: data.tabId,
                html: data.html,
                url: data.url,
                title: data.title,
                isMultiPage: data.isMultiPage,
                maxDepth: linkDepth,
            });
        }, mode, linkDepth);
    });

    onMessage('cancelLoadingLink', async ({ data: taskId }) => {
        await capturing(sentry_scope, "cancelLoadingLink_message_handler", undefined, async () => {
            // Abort fetch controllers immediately in background - this is critical!
            // Don't rely on offscreen to send cancelFetch back because:
            // 1. cancelProcessing is fire-and-forget (returns void)
            // 2. The offscreen document may be closed before cancelFetch is processed
            const controller = fetchAbortControllers.get(taskId as string);
            if (controller) {
                controller.abort();
            }

            // Only send cancelProcessing if offscreen document still exists
            // (it might have been closed if download completed/failed before cancel was clicked)
            if (await offscreenDocumentExists()) {
                await sendMessage('cancelProcessing', taskId as string);
            }
        });
    });

    onMessage('fetchUrl', async ({ data }): Promise<FetchUrlResponse> => {
        const { taskId, url, isText, timeoutMs, sizeLimits } = data as FetchUrlRequest;
        const taskController = getOrCreateAbortController(taskId);
        const timeoutController = new AbortController();
        let timeoutId: ReturnType<typeof setTimeout> | null = null;

        try {
            if (timeoutMs > 0) {
                timeoutId = setTimeout(() => timeoutController.abort(), timeoutMs);
            }

            const signal = AbortSignal.any([taskController.signal, timeoutController.signal]);

            // Track network time
            const networkStart = performance.now();
            const response = await fetch(url, { method: "GET", signal });

            if (!response.ok) {
                return {
                    success: false,
                    errorMessage: `HTTP ${response.status}`
                };
            }

            // Validate by Content-Length based on content-type
            if (sizeLimits) {
                const contentType = response.headers.get("content-type");
                const maxSizeKb = getMaxSizeForContentType(contentType, sizeLimits);
                const contentLengthHeader = response.headers.get("content-length");
                if (contentLengthHeader) {
                    const sizeBytes = parseInt(contentLengthHeader, 10);
                    if (sizeBytes > maxSizeKb * 1024) {
                        try { timeoutController.abort(); } catch (_) {}
                        return {
                            success: false,
                            errorMessage: "file size exceeds the value. Skipped."
                        };
                    }
                }
            }

            if (isText) {
                const text = await response.text();
                const networkMs = performance.now() - networkStart;
                return {
                    success: true,
                    data: text,
                    sizeBytes: new TextEncoder().encode(text).length,
                    timing: { networkMs, encodeMs: 0 },
                };
            } else {
                // ArrayBuffer -> base64 data URL with original content-type
                const buffer = new Uint8Array(await response.arrayBuffer());
                const networkMs = performance.now() - networkStart;

                const encodeStart = performance.now();
                const ctype = response.headers.get("content-type") || "application/octet-stream";
                // Optimized Base64 encoding using chunks to avoid O(n²) string concatenation
                const CHUNK_SIZE = 8192;
                const chunks: string[] = [];
                for (let i = 0; i < buffer.length; i += CHUNK_SIZE) {
                    const chunk = buffer.subarray(i, Math.min(i + CHUNK_SIZE, buffer.length));
                    chunks.push(String.fromCharCode.apply(null, chunk as unknown as number[]));
                }
                const base64 = btoa(chunks.join(''));
                const dataUrl = "data:" + ctype + ";base64," + base64;
                const encodeMs = performance.now() - encodeStart;

                return {
                    success: true,
                    data: dataUrl,
                    sizeBytes: buffer.length,
                    timing: { networkMs, encodeMs },
                };
            }
        } catch (e: any) {
            if (e && (e.name === "AbortError" || e.message === "The user aborted a request.")) {
                return {
                    success: false,
                    errorMessage: "Timeout. skipped."
                };
            }
            return {
                success: false,
                errorMessage: e?.message || "Failed to fetch"
            };
        } finally {
            if (timeoutId) clearTimeout(timeoutId);
        }
    });

    onMessage('cancelFetch', async ({ data: taskId }) => {
        const controller = fetchAbortControllers.get(taskId as string);
        if (controller) {
            controller.abort();
            // Don't delete the controller - keep it so subsequent fetchUrl requests
            // for this taskId will see the aborted signal. This fixes the race condition
            // where new requests arriving after cancel would create a fresh controller.
        }
    });

    onMessage('logPerformanceStats', async ({ data: stats }) => {
        if (isDevelopmentMode()) {
            console.log(stats);
        }
    });

    // Listen for tab updates (reload, navigation) to clear the failed injection flag
    chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
        if (changeInfo.status === 'complete') {
            // Tab has reloaded, content script should be injected automatically
            await removeFailedInjectionTab(tabId);
        }
    });

    // Clean up when tabs are closed
    chrome.tabs.onRemoved.addListener(async (tabId) => {
        await removeFailedInjectionTab(tabId);
    });

    const UNINSTALL_URL = "https://extensiontechnologies-332ae.web.app/website_downloader_uninstall";
    getOrCreateUserId().then(userId => {
        chrome.runtime.setUninstallURL(`${UNINSTALL_URL}?id=${userId}`);
    });
});

async function action_button_clicked(tab: Tab) {
    if (!isSidePanelAvailable()) {
        console.error("Service Worker: Sidepanel API is not available");
        return;
    }

    let tabId = tab.id;
    if (tabId) {
        await chrome.sidePanel.open({tabId: tabId});
    } else {
        console.error("Service Worker: Cannot detect tabId")
    }
}
